"""Inline SVG icons matching the Ink Room and Paper Room visual reference.

No CDN or external icon fonts. 100% offline, self-contained SVG strings.
"""

from html import escape


def svg_icon(name: str, size: int = 18, color: str = "currentColor", extra_class: str = "") -> str:
    """Return an inline SVG string for the requested icon name."""
    paths = ICONS.get(name, ICONS["help"])
    cls_attr = f' class="redline-icon {extra_class}"' if extra_class else ' class="redline-icon"'
    return (
        f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
        f'stroke="{escape(color)}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" '
        f'aria-hidden="true"{cls_attr}>{paths}</svg>'
    )


